<script setup lang="ts">
import { onBeforeUnmount, onMounted, ref } from 'vue';
import { useRouter } from 'vue-router';
import { collaborationApi, type Permission } from '../services/collaboration';

const router=useRouter();
const authenticated=ref(false); const error=ref(''); const message=ref(''); const busy=ref(false);
const cases=ref<any[]>([]); const selectedCaseId=ref(''); const members=ref<any[]>([]); const presence=ref<any[]>([]); const events=ref<any[]>([]); const invitations=ref<any[]>([]);
const email=ref(''); const permission=ref<'read'|'edit'>('read'); const user=ref<any>(null); let timer:number|undefined;
function currentCase(){return cases.value.find(c=>c.id===selectedCaseId.value);}
function authState(){try{const t=localStorage.getItem('mindplace:sync-token');user.value=JSON.parse(localStorage.getItem('mindplace:sync-user')||'null');authenticated.value=!!t;}catch{authenticated.value=false;}}
async function loadCases(){try{cases.value=await collaborationApi.listCases();if(!selectedCaseId.value&&cases.value[0])selectedCaseId.value=cases.value[0].id;if(selectedCaseId.value)await selectCase(selectedCaseId.value);const inv=await collaborationApi.invitations();invitations.value=inv.invitations||[];}catch(e:any){error.value=e?.message||'No se pudieron cargar los casos.';}}
async function selectCase(id:string){selectedCaseId.value=id;message.value='';try{const [m,p,a]=await Promise.all([collaborationApi.members(id),collaborationApi.getPresence(id),collaborationApi.activity(id)]);members.value=m.members||[];presence.value=p.presence||[];events.value=a.events||[];await heartbeat();}catch(e:any){error.value=e?.message||'No se pudo cargar la colaboración.';}}
async function share(){if(!selectedCaseId.value||!email.value.trim())return;busy.value=true;error.value='';message.value='';try{const result=await collaborationApi.share(selectedCaseId.value,email.value.trim(),permission.value);message.value=result.invited?'Invitación preparada: el usuario debe crear/usar esa cuenta y aceptar la invitación.':'Acceso compartido correctamente.';email.value='';await selectCase(selectedCaseId.value);}catch(e:any){error.value=e?.message||'No se pudo compartir el caso.';}finally{busy.value=false;}}
async function setPermission(member:any){if(!selectedCaseId.value)return;busy.value=true;try{await collaborationApi.permission(selectedCaseId.value,member.userId,member.permission==='edit'?'read':'edit');await selectCase(selectedCaseId.value);}catch(e:any){error.value=e?.message||'No se pudo cambiar el permiso.';}finally{busy.value=false;}}
async function removeMember(member:any){if(!selectedCaseId.value)return;busy.value=true;try{await collaborationApi.remove(selectedCaseId.value,member.userId);await selectCase(selectedCaseId.value);}catch(e:any){error.value=e?.message||'No se pudo quitar al colaborador.';}finally{busy.value=false;}}
async function acceptInvitation(inv:any){busy.value=true;try{await collaborationApi.acceptInvitation(inv.id);message.value='Invitación aceptada.';await loadCases();}catch(e:any){error.value=e?.message||'No se pudo aceptar la invitación.';}finally{busy.value=false;}}
async function heartbeat(){if(!selectedCaseId.value||!authenticated.value)return;try{await collaborationApi.presence(selectedCaseId.value,'viewing',user.value?.name||user.value?.email);const p=await collaborationApi.getPresence(selectedCaseId.value);presence.value=p.presence||[];}catch(e:any){/* presencia no debe bloquear el caso */}}
async function refreshActivity(){if(selectedCaseId.value)try{const [p,a]=await Promise.all([collaborationApi.getPresence(selectedCaseId.value),collaborationApi.activity(selectedCaseId.value)]);presence.value=p.presence||[];events.value=a.events||[];}catch(_){} }
function fmt(ts:number){return new Date(ts).toLocaleString();}
function label(action:string){return ({'member.shared':'compartió el caso','member.permission_changed':'cambió un permiso','member.removed':'quitó un colaborador','invitation.created':'creó una invitación','invitation.accepted':'aceptó una invitación','case.updated':'actualizó el caso'} as any)[action]||action;}
onMounted(()=>{authState();if(authenticated.value)void loadCases();timer=window.setInterval(()=>void refreshActivity(),5000);});
onBeforeUnmount(()=>{if(timer)window.clearInterval(timer);if(selectedCaseId.value&&authenticated.value)void collaborationApi.leave(selectedCaseId.value);});
</script>
<template>
<main class="phase33">
<header><div><p class="eyebrow">FASE 33 · 395–403</p><h1>Colaboración de casos</h1><p>Compartición por usuario, permisos, modo lectura/edición, presencia, actividad y compatibilidad con la sincronización de la Fase 32.</p></div><button @click="router.push('/')">← Tablero</button></header>
<section v-if="!authenticated" class="notice"><h2>Sesión necesaria</h2><p>La colaboración usa la cuenta de MindPlace de la Fase 32. Inicia sesión allí y vuelve a esta vista.</p><button @click="router.push('/fase-32')">Ir a Fase 32</button></section>
<template v-else>
<section class="toolbar"><span class="pill">{{ user?.email }}</span><span class="pill">{{ cases.length }} casos con acceso</span><span class="pill">{{ presence.length }} conectados ahora</span></section>
<section v-if="invitations.length" class="panel"><div class="panelHead"><div><h2>Invitaciones pendientes</h2><small>Las invitaciones quedan asociadas a la cuenta receptora hasta su aceptación.</small></div></div><div v-for="inv in invitations" :key="inv.id" class="invite"><div><strong>{{ inv.email }}</strong><span>{{ inv.permission==='edit'?'Edición':'Lectura' }}</span></div><button :disabled="busy" @click="acceptInvitation(inv)">Aceptar</button></div></section>
<section class="layout">
<div class="panel cases"><h2>Casos</h2><button v-for="c in cases" :key="c.id" :class="['caseBtn',{active:c.id===selectedCaseId}]" @click="selectCase(c.id)"><strong>{{ c.id }}</strong><span>{{ c.permission==='owner'?'Propietario':c.permission==='edit'?'Edición':'Lectura' }} · v{{ c.version }}</span></button><p v-if="!cases.length" class="muted">No hay casos remotos para esta cuenta.</p></div>
<div class="stack" v-if="selectedCaseId">
<section class="panel"><div class="panelHead"><div><h2>Compartir caso</h2><small>{{ selectedCaseId }} · {{ currentCase()?.permission==='owner'?'eres propietario':`permiso ${currentCase()?.permission}` }}</small></div></div><div v-if="currentCase()?.permission==='owner'" class="shareForm"><input v-model="email" type="email" placeholder="email@ejemplo.com" @keyup.enter="share"><select v-model="permission"><option value="read">Solo lectura</option><option value="edit">Puede editar</option></select><button :disabled="busy||!email.trim()" @click="share">Compartir</button></div><p v-else class="muted">Solo el propietario administra los colaboradores.</p></section>
<section class="panel"><div class="panelHead"><div><h2>Personas con acceso</h2><small>Modo lectura evita cambios; edición usa el mismo control de versiones y conflictos de la Fase 32.</small></div></div><div v-for="m in members" :key="m.userId" class="member"><div class="avatar">{{ (m.name||m.email||'?').slice(0,1).toUpperCase() }}</div><div class="who"><strong>{{ m.name||m.email }}</strong><small>{{ m.email }}</small></div><span class="permission" :class="m.permission">{{ m.permission==='owner'?'Propietario':m.permission==='edit'?'Edición':'Lectura' }}</span><template v-if="currentCase()?.permission==='owner'&&m.permission!=='owner'"><button @click="setPermission(m)" :title="m.permission==='edit'?'Cambiar a lectura':'Dar edición'">{{ m.permission==='edit'?'Lectura':'Edición' }}</button><button class="danger" @click="removeMember(m)">Quitar</button></template></div></section>
<section class="panel"><div class="panelHead"><div><h2>Colaboración activa</h2><small>Presencia temporal con latido cada 5 segundos.</small></div><button @click="heartbeat">Actualizar</button></div><div class="presence"><span v-for="p in presence" :key="p.userId" class="presenceItem"><i></i>{{ p.displayName||p.email }}<small>{{ p.me?'Tú':'activo' }}</small></span></div></section>
<section class="panel"><div class="panelHead"><div><h2>Historial de colaboración</h2><small>Auditoría separada del Undo/Redo y del versionado del caso.</small></div></div><div v-for="e in events" :key="e.id" class="event"><strong>{{ e.actorName }}</strong><span>{{ label(e.action) }}</span><small>{{ fmt(e.createdAt) }}<template v-if="e.version"> · v{{ e.version }}</template></small></div><p v-if="!events.length" class="muted">Todavía no hay actividad de colaboración.</p></section>
</div></section>
<section class="matrix"><article><b>395–396</b><h3>Compartir y permisos</h3><p>El propietario puede añadir usuarios y asignar lectura o edición.</p></article><article><b>397–398</b><h3>Modo lectura / edición</h3><p>El backend bloquea escrituras a colaboradores de solo lectura.</p></article><article><b>399–402</b><h3>Colaboración simultánea</h3><p>Presencia temporal + control optimista de versiones para detectar conflictos.</p></article><article><b>403</b><h3>Historial</h3><p>Los cambios de colaboración quedan registrados sin mezclarlo con Undo/Redo.</p></article></section>
</template><p v-if="error" class="error">{{ error }}</p><p v-if="message" class="success">{{ message }}</p>
</main>
</template>
<style scoped>
.phase33{min-height:100dvh;box-sizing:border-box;padding:22px;color:#e8eef6;background:#0b1120;font:14px/1.45 Inter,system-ui,sans-serif}.phase33 header{display:flex;justify-content:space-between;gap:18px;align-items:flex-start}.eyebrow{font-size:11px;letter-spacing:.16em;color:#91a2bb;font-weight:800}.phase33 h1{margin:4px 0 7px;font-size:clamp(28px,5vw,46px)}.phase33 header p:not(.eyebrow),.panel small,.muted{color:#93a1b5}.phase33 button{border:1px solid #33455d;background:#172237;color:#edf3fa;border-radius:10px;padding:10px 13px;font:inherit;cursor:pointer}.phase33 button:disabled{opacity:.5;cursor:not-allowed}.notice,.panel,.matrix article{margin-top:18px;padding:18px;border:1px solid #25354b;background:#111b2c;border-radius:15px}.toolbar{display:flex;gap:8px;flex-wrap:wrap;margin-top:18px}.pill,.permission,.presenceItem{display:inline-flex;align-items:center;gap:6px;padding:7px 10px;border-radius:999px;background:#172237;border:1px solid #2c3c53;color:#bdc9d9}.layout{display:grid;grid-template-columns:270px 1fr;gap:16px;margin-top:18px}.cases{align-self:start;display:grid;gap:8px}.caseBtn{display:grid;text-align:left;gap:3px}.caseBtn span{font-size:12px;color:#93a1b5}.caseBtn.active{outline:2px solid #7896bb}.stack{display:grid;gap:16px}.panelHead{display:flex;align-items:center;justify-content:space-between;gap:15px;margin-bottom:12px}.panelHead h2,.panel h2{margin:0}.shareForm{display:grid;grid-template-columns:1fr auto auto;gap:8px}.shareForm input,.shareForm select{background:#101a2a;border:1px solid #2b3b52;color:#fff;border-radius:9px;padding:10px 12px;font:inherit}.member{display:grid;grid-template-columns:auto 1fr auto auto auto;gap:10px;align-items:center;padding:10px 0;border-top:1px solid #223148}.avatar{width:34px;height:34px;border-radius:50%;display:grid;place-items:center;background:#22334d}.who{display:grid}.who small{font-size:12px}.permission.owner{background:#20334a}.permission.edit{background:#213b35}.permission.read{background:#332f21}.danger{border-color:#5a3740!important}.presence{display:flex;flex-wrap:wrap;gap:8px}.presenceItem{padding:8px 10px}.presenceItem i{width:8px;height:8px;border-radius:50%;background:#70d7ab}.presenceItem small{font-size:11px}.invite,.event{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:10px 0;border-top:1px solid #223148}.invite>div{display:grid;gap:3px}.invite span{font-size:12px;color:#9fb0c6}.event{justify-content:flex-start}.event span{color:#b6c2d3}.event small{margin-left:auto}.matrix{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-top:18px}.matrix article{margin-top:0}.matrix h3{margin:5px 0}.matrix p{margin:0;color:#93a1b5}.error,.success{margin-top:14px;padding:10px 12px;border-radius:10px}.error{color:#ffb4b4;background:#331d24;border:1px solid #693540}.success{color:#9be6c2;background:#173128;border:1px solid #2b5f4c}@media(max-width:900px){.layout{grid-template-columns:1fr}.matrix{grid-template-columns:repeat(2,1fr)}}@media(max-width:620px){.phase33{padding:14px 12px 80px}.phase33 header{flex-direction:column}.shareForm{grid-template-columns:1fr}.member{grid-template-columns:auto 1fr auto}.member .danger,.member button{grid-column:2}.matrix{grid-template-columns:1fr}.event{align-items:flex-start;flex-wrap:wrap}.event small{margin-left:0;width:100%}}
</style>
